import importlib
import openai_client as oc

try:
    oc.OpenAIClient(api_key=None)
except ValueError as e:
    print(\"ValueError as expected:\", e)

c = oc.OpenAIClient(api_key=\"sk-test\")
print(\"client ok\", c.model, c.base_url)

sample = {
    \"output\": [
        {\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"Hello there\"}]}
    ]
}
print(oc.extract_output_text(sample))
